
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_ft97_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_ft97", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.295660090715223e-02, -5.238703109726714e-02, -5.185624039874186e-02, -5.145702809214206e-02, -5.115209834617552e-02, -5.078833469403921e-02, -5.012665948532596e-02, -4.819770433264269e-02, -4.001565798611468e-02, -1.193659216980227e-02, -1.029966816089769e-02, -2.166477187538475e-02, -5.053426053993430e-02, -3.836866445049088e-02, -7.613429253907523e-03, -1.683808337860185e-06, 0.000000000000000e+00, 0.000000000000000e+00, 0.000000000000000e+00, 0.000000000000000e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


